class Father {
int x = 0;
void m1() { System.out.println("m1"); }
void m2() { System.out.println("m2"); }
}
class Son extends Father {
int y = 2;
void m2() { System.out.println("m2-overridden"); }
}
public class CallOverriddenMethod {
